import React, { useState, useRef } from 'react';
import './CreateInvitation.css';
import { GoogleMap, LoadScript, Marker, Autocomplete } from '@react-google-maps/api';
import { useInView } from 'react-intersection-observer';
import { motion } from 'framer-motion';
import couple2 from '../images/couple2.png';
import flower2 from '../images/flower2.png';
import { format } from 'date-fns';
import { uz } from 'date-fns/locale';
import Countdown from './Countdown';
import Calendar from './Calendar';
import Modal_preview from './Modal_preview';
import couple3 from '../images/couple3.png';
import couple1 from '../images/couple.png';

const defaultWeddingDetails = {
  brideName: '',
  groomName: '',
  weddingDate: '',
  weddingTime: '',
  weddingLocation: '',
  theme: 'classic',
  customText: 'Sizni to’yga bag’ishlangan bayramga taklif qilamiz...',
  selectedPhoto: couple1,
  locationCoords: null,
};

const CreateInvitation = () => {
  const [weddingDetails, setWeddingDetails] = useState(defaultWeddingDetails);
  const [modalOpen, setModalOpen] = useState(false);
  const [isTextEditable, setIsTextEditable] = useState(false);
  const [customImage, setCustomImage] = useState(null);
  const [selectedPhoto, setSelectedPhoto] = useState(couple1);
  const [invitationId, setInvitationId] = useState(null);
  const autocompleteRef = useRef(null);

  const handleSave = async () => {
    if (!weddingDetails.brideName || !weddingDetails.groomName ||
      !weddingDetails.weddingDate || !weddingDetails.weddingTime ||
      !weddingDetails.weddingLocation || !weddingDetails.locationCoords) {
      alert('Пожалуйста, заполните все обязательные поля, включая локацию.');
      return;
    }

    try {
      const response = await fetch('http://localhost:5001/api/invitations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(weddingDetails),
      });

      if (!response.ok) {
        const errorMessage = await response.text();
        throw new Error(`Ошибка при сохранении: ${errorMessage}`);
      }

      const data = await response.json();
      setInvitationId(data._id);
      setModalOpen(true);
    } catch (error) {
      console.error('Ошибка при сохранении:', error);
      alert('Произошла ошибка при сохранении.');
    }
  };

  const handleLocationSelect = () => {
    const place = autocompleteRef.current.getPlace();
    if (place.geometry) {
      const lat = place.geometry.location.lat();
      const lng = place.geometry.location.lng();
      setWeddingDetails(prev => ({
        ...prev,
        locationCoords: { lat, lng },
        weddingLocation: place.formatted_address,
      }));
    }
  };

  return (
    <div className="invitation-container">
      <form>
        <label htmlFor="brideName">Kelin nomi:</label>
        <input type="text" name="brideName" value={weddingDetails.brideName} onChange={e => setWeddingDetails(prev => ({ ...prev, brideName: e.target.value }))} />

        <label>Выберите местоположение:</label>
        <Autocomplete onLoad={ref => (autocompleteRef.current = ref)} onPlaceChanged={handleLocationSelect}>
          <input type="text" placeholder="Введите место" className="autocomplete-input" />
        </Autocomplete>

        <GoogleMap
          mapContainerStyle={{ width: '100%', height: '400px' }}
          center={weddingDetails.locationCoords || { lat: 41.2995, lng: 69.2401 }}
          zoom={15}
        >
          {weddingDetails.locationCoords && <Marker position={weddingDetails.locationCoords} />}
        </GoogleMap>

        <button onClick={handleSave}>Сохранить и открыть приглашение</button>
      </form>

      {modalOpen && (
        <Modal_preview isOpen={modalOpen} onClose={() => setModalOpen(false)}>
          <GoogleMap
            mapContainerStyle={{ width: '100%', height: '400px' }}
            center={weddingDetails.locationCoords}
            zoom={15}
          >
            <Marker position={weddingDetails.locationCoords} />
          </GoogleMap>
        </Modal_preview>
      )}
    </div>
  );
};

export default CreateInvitation;
